head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vIsurCd = "";
scwin.vBackListDesignDD = "";
// 세션정보를 얻기위한 함수사용
scwin.TR_JOB;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        $c.cm.PanelToGroupBox(panel_2);
        $c.cm.PanelToGroupBox(panel_Top);
        scwin.setComboCode();
        const parentWin = $c.frame.path("../");
        scwin.vIsurCd = parentWin.clickIsurCd;
        scwin.vBackListDesignDD = parentWin.clickBackListDesignDD;

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제

        if (scwin.vIsurCd === "") {
            scwin.initForm("C");
            const sbmOptions = {
                id : "sbm_dts_Item",
                action : "/gauceSystemierAdaptor.do",
                ref : "",
                target : "dts_Item=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

            dts_Item.insertRow();
        } else {
            txb_ISUR_CD.setValue(scwin.vIsurCd);
            edt_BACKLIST_DESIGN_DD.setValue(scwin.vBackListDesignDD);
            edt_BACKLIST_DESIGN_DD.setReadOnly(true);
            scwin.initForm("X");
            buttonSet.setUpdateStatus();
            await scwin.searchSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41531.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_CoSearch_onclick
 * @description img_CoSearch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_CoSearch_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41531.img_CoSearch_onclick" });
    }
};

/**
 * @method
 * @name img_BACKLIST_DISCLS_DD_onclick
 * @description img_BACKLIST_DISCLS_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_BACKLIST_DISCLS_DD_onclick = function() {
    try {
        popUpCalendar2(edt_BACKLIST_DISCLS_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41531.img_BACKLIST_DISCLS_DD_onclick" });
    }
};

/**
 * @method
 * @name img_BACKLIST_DESIGN_DD_onclick
 * @description img_BACKLIST_DESIGN_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_BACKLIST_DESIGN_DD_onclick = function() {
    try {
        popUpCalendar2(edt_BACKLIST_DESIGN_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41531.img_BACKLIST_DESIGN_DD_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.searchSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41531.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41531.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name dts_DoubleChk_OnLoadError
 * @description dts_DoubleChk 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DoubleChk_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_DoubleChk);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41531.dts_DoubleChk_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Item_OnLoadError
 * @description dts_Item 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Item_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Item);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41531.dts_Item_OnLoadError" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        $c.lc.fn_alertMsg('F');
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41531.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        scwin.initForm("X");
        buttonSet.setUpdateStatus();
        scwin.parentRefresh();
        if (scwin.TR_JOB === "D") {
            await $c.win.closePopup();
        } else {
            await scwin.searchSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41531.trs_Save_OnSuccess" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchSync
 * @description 우회상장회사 정보조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchSync = async function() {
    const pIsurCd = txb_ISUR_CD.getValue();
    const pComNm = txb_COM_NM.getValue();
    const pDesignDd = edt_BACKLIST_DESIGN_DD.getValue();
    const pDisclsDd = edt_BACKLIST_DISCLS_DD.getValue();
    const pAdmTpCd = cmb_BACKLIST_ADM_TP_CD.getValue();
    url += "&method=searchBackListComDetail";
    url += "&inputMessageId=BACKLIST_COM_INPUT_OUT";
    url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    url += "&BACKLIST_DESIGN_DD=" + edt_BACKLIST_DESIGN_DD.getValue();
    const sbmOptions = {
        id : "sbm_dts_Item",
        action : "/RepMajagnt.do",
        ref : "",
        target : "dts_Item=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (txb_ISUR_CD.getValue() === "" || edt_BACKLIST_DESIGN_DD.getValue() === "") {
        await $c.win.alert("[해당회사는 입력 데이터가 없습니다.]");
        dts_Item.insertRow();
        txb_ISUR_CD.setValue(pIsurCd);
        txb_COM_NM.setValue(pComNm);
        edt_BACKLIST_DESIGN_DD.setValue(pDesignDd);
        edt_BACKLIST_DISCLS_DD.setValue(pDisclsDd);
        cmb_BACKLIST_ADM_TP_CD.setSelectedIndex((pAdmTpCd - 1));
    }
};

/**
 * @method
 * @name checkDoubleInput
 * @description 신규입력시 중복입력여부를 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkDoubleInput = async function() {
    url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    url += "&BACKLIST_DESIGN_DD=" + edt_BACKLIST_DESIGN_DD.getValue();
    const sbmOptions = {
        id : "sbm_dts_DoubleChk",
        action : "/RepMajagnt.do",
        ref : "",
        target : "dts_DoubleChk=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const str = dts_DoubleChk.getCellData(1, "DBINPUT_YN");
    if (str === 'Y') {
        await $c.win.alert("[해당종목은 이미 동일한 우회상장지정일에 입력 데이터가 있습니다.]");
        return false;
    } else if (str === 'N') {
        return true;
    }
};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @param {*} jobType jobType
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function(jobType) {
    let vScrenTpCD;
    if (scwin.TR_JOB === 'I') {
        vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB === 'U') {
        vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB === 'D') {
        vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }
    scwin.setDataItem();
    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     JOB_TYPE : jobType
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/RepMajagnt.do",
        ref : "dts_Item",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initForm
 * @description init Form 처리
 * @param {*} initTyp initTyp
 * @returns {void}
 * @hidden N
 */
scwin.initForm = function(initTyp) {
    if (initTyp === "C") {
        img_CoSearch.setBackgroundImage("../img/btn_search.gif");
        img_CoSearch.setDisabled(false);
    } else if (initTyp === "X") {
        img_CoSearch.setBackgroundImage("../img/btn_search_d.gif");
        img_CoSearch.setDisabled(true);
        btn_Search.setBackgroundImage("../img/btn_select_d.gif");
        btn_Search.setDisabled(true);
        img_BACKLIST_DESIGN_DD.src = "../img/icn_calendar_d.gif";
        img_BACKLIST_DESIGN_DD.setDisabled(true);
    }
};

/**
 * @method
 * @name setComboCode
 * @description set Combo Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setComboCode = function() {
    const strCode = "1^합병,2^포괄적 주식교환,3^영업양수,4^자산양수,5^현물출자,6^기타";
    cmb_BACKLIST_ADM_TP_CD.CBData = strCode;
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (txb_ISUR_CD.getValue() === "") {
        await $c.win.alert("[회사]를 선택하세요.");
        txb_ISUR_CD.focus();
        return false;
    }
    if (edt_BACKLIST_DISCLS_DD.getValue() === "") {
        await $c.win.alert("[우회상장 공시일]을 입력하세요.");
        edt_BACKLIST_DISCLS_DD.focus();
        return false;
    }
    if (edt_BACKLIST_DESIGN_DD.getValue() === "") {
        await $c.win.alert("[우회상장 지정일]을 입력하세요.");
        edt_BACKLIST_DESIGN_DD.focus();
        return false;
    }
    if (cmb_BACKLIST_ADM_TP_CD.getValue() === "") {
        await $c.win.alert("[우회상장 유형]을 선택하세요.");
        cmb_BACKLIST_ADM_TP_CD.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name setDataItem
 * @description set Data Item 처리
 * @returns {void}
 * @hidden N
 */
scwin.setDataItem = function() {
    dts_Item.setCellData(1, "ISUR_CD", txb_ISUR_CD.getValue());
    dts_Item.setCellData(1, "BACKLIST_DESIGN_DD", edt_BACKLIST_DESIGN_DD.getValue());
    dts_Item.setCellData(1, "BACKLIST_DISCLS_DD", edt_BACKLIST_DISCLS_DD.getValue());
    dts_Item.setCellData(1, "BACKLIST_ADM_TP_CD", cmb_BACKLIST_ADM_TP_CD.getValue());
    dts_Item.setCellData(1, "BACKLIST_ACNTG_CORP_NM", txb_BACKLIST_ACNTG_CORP_NM.getValue());
    dts_Item.setCellData(1, "BACKLIST_AGNCCOM_NM", txb_BACKLIST_AGNCCOM_NM.getValue());
    dts_Item.setCellData(1, "EXT_VALU_INST_NM", txb_EXT_VALU_INST_NM.getValue());
    dts_Item.setCellData(1, "LIST_CORP_ASST_TOTAMT", edt_LIST_CORP_ASST_TOTAMT.getValue());
    dts_Item.setCellData(1, "LIST_CORP_SALES", edt_LIST_CORP_SALES.getValue());
    dts_Item.setCellData(1, "LIST_CORP_DEBT_TOTAMT", edt_LIST_CORP_DEBT_TOTAMT.getValue());
    dts_Item.setCellData(1, "LIST_CORP_OPERPROFT_AMT", edt_LIST_CORP_OPERPROFT_AMT.getValue());
    dts_Item.setCellData(1, "LIST_CORP_CAP", edt_LIST_CORP_CAP.getValue());
    dts_Item.setCellData(1, "LIST_CORP_ORDNINCM_AMT", edt_LIST_CORP_ORDNINCM_AMT.getValue());
    dts_Item.setCellData(1, "LIST_CORP_CAP_TOTAMT", edt_LIST_CORP_CAP_TOTAMT.getValue());
    dts_Item.setCellData(1, "LIST_CORP_NETINCM", edt_LIST_CORP_NETINCM.getValue());
    dts_Item.setCellData(1, "NLIST_CORP_NM", txb_NLIST_CORP_NM.getValue());
    dts_Item.setCellData(1, "NLIST_ACNTG_CORP_NM", txb_NLIST_ACNTG_CORP_NM.getValue());
    dts_Item.setCellData(1, "NLIST_CORP_ASST_TOTAMT", edt_NLIST_CORP_ASST_TOTAMT.getValue());
    dts_Item.setCellData(1, "NLIST_CORP_SALES", edt_NLIST_CORP_SALES.getValue());
    dts_Item.setCellData(1, "NLIST_CORP_DEBT_TOTAMT", edt_NLIST_CORP_DEBT_TOTAMT.getValue());
    dts_Item.setCellData(1, "NLIST_CORP_OPERPROFT_AMT", edt_NLIST_CORP_OPERPROFT_AMT.getValue());
    dts_Item.setCellData(1, "NLIST_CORP_CAP", edt_NLIST_CORP_CAP.getValue());
    dts_Item.setCellData(1, "NLIST_CORP_ORDNINCM_AMT", edt_NLIST_CORP_ORDNINCM_AMT.getValue());
    dts_Item.setCellData(1, "NLIST_CORP_CAP_TOTAMT", edt_NLIST_CORP_CAP_TOTAMT.getValue());
    dts_Item.setCellData(1, "NLIST_CORP_NETINCM", edt_NLIST_CORP_NETINCM.getValue());
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    scwin.TR_JOB = 'I';
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        if ($c.pre_newlisting.fn_checkDoubleInput()) {
            await scwin.trs(TR_JOB_INSERT);
        }
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    scwin.TR_JOB = 'U';
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        await scwin.trs(TR_JOB_UPDATE);
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    scwin.TR_JOB = 'D';
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        await scwin.trs(TR_JOB_DELETE);
    }
};

/**
 * @method
 * @name parentRefresh
 * @description parent Refresh 처리
 * @returns {void}
 * @hidden N
 */
scwin.parentRefresh = function() {
    const fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};
